# -*- coding: utf-8 -*-
# =============================================================================
# 컴포넌트 개요: 00C 실시간 생산 결정론 공정그룹 선택 Gate
# 역할: 질문 원문에 명시된 Domain 공정그룹을 규칙으로 하나만 선택하고 해당 행만 통과시킵니다.
# 주요 입력: 사용자 질문, 공정그룹 카탈로그, 전체 판정 Snapshot
# 주요 출력: 선택된 production.judgement.dataset.v1 또는 clarification/error 계약 Data
# 처리 흐름: 계약 검증 -> 질문 증거 검색 -> 단일 그룹 확정 -> field/processes 허용목록 필터
# 유지보수 포인트: 의미 추측이나 기본 그룹 선택 없이 metadata에 등록된 표현만 정확히 허용합니다.
# =============================================================================

from __future__ import annotations

import re
from copy import deepcopy
from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, HandleInput, Output
from lfx.schema.data import Data


CONTRACT_VERSION = "production.process_group.selection.v1"
DATASET_CONTRACT_VERSION = "production.judgement.dataset.v1"
CATALOG_CONTRACT_VERSION = "domain.process_group.catalog.v1"
SELECTION_METHOD = "deterministic_explicit_match"
MAX_QUESTION_CHARS = 4_000


# 함수 설명: `_text()`는 Message 또는 일반 입력을 질문 검증용 문자열로 변환합니다.
def _text(value: Any) -> str:
    if value is None:
        return ""
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        candidate = getattr(value, "text", None) or data.get("text")
        if candidate is not None:
            return str(candidate).strip()
    return str(getattr(value, "text", value) or "").strip()


# 함수 설명: `_payload()`는 Langflow Data 또는 dict 입력을 독립 복사된 페이로드로 변환합니다.
def _payload(value: Any) -> dict[str, Any]:
    raw = getattr(value, "data", value)
    return deepcopy(raw) if isinstance(raw, dict) else {}


# 함수 설명: `_empty_llm_decision()`은 기존 selection.v1 공개 shape와의 호환을 유지합니다.
def _empty_llm_decision() -> dict[str, Any]:
    return {
        "status": "",
        "process_group_key": "",
        "reason": "",
        "evidence": [],
    }


# 함수 설명: `_selection_provenance()`는 모델을 사용하지 않은 선택 근거만 제한된 크기로 기록합니다.
def _selection_provenance(
    matches: dict[str, list[str]],
    *,
    selected_key: str = "",
) -> dict[str, Any]:
    return {
        "method": SELECTION_METHOD,
        "catalog_contract_version": CATALOG_CONTRACT_VERSION,
        "matched_group_count": len(matches),
        "selected_key": str(selected_key or ""),
        "question_evidence": {
            str(key): [str(item)[:200] for item in evidence[:20]]
            for key, evidence in matches.items()
        },
    }


# 함수 설명: `_token_present()`는 등록 표현의 영숫자 경계를 지켜 D/A1과 D/A10 같은 prefix 오탐을 차단합니다.
def _token_present(question: str, token: str, *, short_key: bool = False) -> bool:
    candidate = str(token or "").strip()
    if not candidate:
        return False
    if short_key or re.search(r"[A-Za-z0-9]", candidate):
        left_boundary = r"(?<![A-Za-z0-9])" if re.match(r"[A-Za-z0-9]", candidate) else ""
        right_boundary = r"(?![A-Za-z0-9])" if re.search(r"[A-Za-z0-9]$", candidate) else ""
        return bool(
            re.search(
                rf"{left_boundary}{re.escape(candidate)}{right_boundary}",
                question,
                flags=re.IGNORECASE,
            )
        )
    return candidate.casefold() in question.casefold()


# 함수 설명: `find_explicit_process_group_matches()`는 key·alias·display·세부 공정 근거를 그룹별로 수집합니다.
def find_explicit_process_group_matches(
    question: str,
    groups: list[dict[str, Any]],
) -> dict[str, list[str]]:
    matches: dict[str, list[str]] = {}
    for group in groups:
        key = str(group.get("key") or "").strip().upper()
        evidence: list[str] = []
        for process in group.get("processes") or []:
            if _token_present(question, str(process)):
                evidence.append(str(process))
        for alias in group.get("aliases") or []:
            if _token_present(
                question,
                str(alias),
                short_key=str(alias).strip().upper() == key,
            ):
                evidence.append(str(alias))
        display_name = str(group.get("display_name") or "")
        if _token_present(question, display_name):
            evidence.append(display_name)
        if _token_present(question, key, short_key=True):
            evidence.append(key)
        unique = list(dict.fromkeys(item for item in evidence if item))
        if key and unique:
            matches[key] = unique
    return matches


# 함수 설명: `_validated_groups()`는 카탈로그 항목의 필수 schema와 key 유일성을 fail-closed로 검증합니다.
def _validated_groups(catalog: dict[str, Any]) -> tuple[list[dict[str, Any]], list[dict[str, str]]]:
    errors: list[dict[str, str]] = []
    raw_groups = catalog.get("process_groups")
    if not isinstance(raw_groups, list):
        return [], [{"type": "invalid_process_group_catalog_shape", "message": "process_groups가 배열이 아닙니다."}]

    groups: list[dict[str, Any]] = []
    seen_keys: set[str] = set()
    for index, raw_group in enumerate(raw_groups):
        if not isinstance(raw_group, dict):
            errors.append(
                {
                    "type": "invalid_process_group_item",
                    "message": f"공정그룹 #{index + 1}이 object가 아닙니다.",
                }
            )
            continue
        group = deepcopy(raw_group)
        key = str(group.get("key") or "").strip().upper()
        display_name = str(group.get("display_name") or "").strip()
        field = str(group.get("field") or "").strip()
        aliases = group.get("aliases")
        processes = group.get("processes")
        if (
            not key
            or not display_name
            or not field
            or not isinstance(aliases, list)
            or not isinstance(processes, list)
            or not any(str(item or "").strip() for item in processes)
        ):
            errors.append(
                {
                    "type": "invalid_process_group_item",
                    "message": f"공정그룹 #{index + 1}의 key/display_name/aliases/field/processes 계약이 불완전합니다.",
                }
            )
            continue
        if key in seen_keys:
            errors.append(
                {
                    "type": "duplicate_process_group_key",
                    "message": f"중복 공정그룹 key가 있습니다: {key}",
                }
            )
            continue
        seen_keys.add(key)
        group["key"] = key
        group["display_name"] = display_name
        group["field"] = field
        group["aliases"] = [str(item).strip() for item in aliases if str(item or "").strip()]
        group["processes"] = [str(item).strip() for item in processes if str(item or "").strip()]
        groups.append(group)
    return groups, errors


# 함수 설명: `_candidate_summary()`는 재질문 응답에 노출할 공정그룹 후보 필드만 선택합니다.
def _candidate_summary(groups: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [
        {
            "key": str(group.get("key") or ""),
            "display_name": str(group.get("display_name") or ""),
            "aliases": list(group.get("aliases") or []),
            "processes": list(group.get("processes") or []),
        }
        for group in groups
    ]


# 함수 설명: `_clarification_message()`는 미지정 또는 다중지정 상황에서 단일 공정그룹을 요청합니다.
def _clarification_message(groups: list[dict[str, Any]], matched_keys: list[str]) -> str:
    candidates = ", ".join(
        f"`{group.get('display_name') or group.get('key')}`"
        for group in groups
    ) or "등록된 공정그룹 없음"
    if len(matched_keys) > 1:
        matched = ", ".join(f"`{key}`" for key in matched_keys)
        lead = f"여러 공정그룹({matched})이 함께 확인되어 하나를 선택해야 합니다."
    else:
        lead = "실시간 생산 분석을 실행할 공정그룹이 질문에 없습니다."
    return (
        "### 공정그룹을 선택해 주세요.\n\n"
        f"{lead} Report는 아직 생성하지 않았습니다.\n\n"
        f"- 선택 가능한 공정그룹: {candidates}\n"
        "- 예시: `W/B 공정 그룹의 실시간 생산 분석 Report를 만들어줘`"
    )


# 함수 설명: `_selection_boundary()`는 Report를 만들지 않는 clarification/error 계약을 생성합니다.
def _selection_boundary(
    *,
    status: str,
    message: str,
    groups: list[dict[str, Any]],
    matches: dict[str, list[str]],
    errors: list[dict[str, str]] | None = None,
) -> dict[str, Any]:
    return {
        "contract_version": CONTRACT_VERSION,
        "response_type": "realtime_production_process_group_selection",
        "status": status,
        "success": status == "clarification_required",
        "message": message,
        "selected_process_group": {},
        "process_group_candidates": _candidate_summary(groups),
        "matched_process_groups": [
            {"key": key, "evidence": evidence}
            for key, evidence in matches.items()
        ],
        "llm_decision": _empty_llm_decision(),
        "selection_provenance": _selection_provenance(matches),
        "errors": list(errors or []),
    }


# 함수 설명: `select_process_group_dataset()`는 질문의 단일 명시 그룹만 선택해 허용된 판정 행을 반환합니다.
def select_process_group_dataset(
    *,
    question_value: Any,
    catalog_value: Any,
    dataset_value: Any,
) -> dict[str, Any]:
    question = _text(question_value)[:MAX_QUESTION_CHARS]
    catalog = _payload(catalog_value)
    groups, group_errors = _validated_groups(catalog)
    if (
        catalog.get("contract_version") != CATALOG_CONTRACT_VERSION
        or catalog.get("status") != "ok"
        or not groups
        or group_errors
    ):
        errors = [
            deepcopy(item)
            for item in catalog.get("errors", [])
            if isinstance(item, dict)
        ]
        errors.extend(group_errors)
        if not errors:
            errors = [{"type": "invalid_process_group_catalog", "message": "사용 가능한 공정그룹 카탈로그가 없습니다."}]
        return _selection_boundary(
            status="error",
            message="### 실시간 생산 분석 오류\n공정그룹 정보를 불러오지 못해 Report를 생성하지 않았습니다.",
            groups=groups,
            matches={},
            errors=errors,
        )

    matches = find_explicit_process_group_matches(question, groups)
    matched_keys = sorted(matches)
    if len(matched_keys) != 1:
        return _selection_boundary(
            status="clarification_required",
            message=_clarification_message(groups, matched_keys),
            groups=groups,
            matches=matches,
            errors=[],
        )

    selected_key = matched_keys[0]
    selected_group = next(
        group
        for group in groups
        if str(group.get("key") or "").strip().upper() == selected_key
    )
    dataset = _payload(dataset_value)
    if dataset.get("contract_version") != DATASET_CONTRACT_VERSION:
        return _selection_boundary(
            status="error",
            message="### 실시간 생산 분석 오류\n판정 데이터 계약을 확인할 수 없어 Report를 생성하지 않았습니다.",
            groups=groups,
            matches=matches,
            errors=[
                {
                    "type": "invalid_production_judgement_dataset_contract",
                    "message": f"판정 데이터 contract_version은 {DATASET_CONTRACT_VERSION}이어야 합니다.",
                }
            ],
        )

    rows = dataset.get("rows")
    columns = dataset.get("columns")
    if not isinstance(rows, list):
        return _selection_boundary(
            status="error",
            message="### 실시간 생산 분석 오류\n판정 데이터 rows를 확인할 수 없어 Report를 생성하지 않았습니다.",
            groups=groups,
            matches=matches,
            errors=[{"type": "missing_dataset_rows", "message": "판정 데이터 rows가 배열이 아닙니다."}],
        )
    if not isinstance(columns, list) or any(not isinstance(row, dict) for row in rows):
        return _selection_boundary(
            status="error",
            message="### 실시간 생산 분석 오류\n판정 데이터 schema를 확인할 수 없어 Report를 생성하지 않았습니다.",
            groups=groups,
            matches=matches,
            errors=[
                {
                    "type": "invalid_production_judgement_dataset_schema",
                    "message": "판정 데이터 columns는 배열이고 모든 rows 항목은 object여야 합니다.",
                }
            ],
        )

    field = str(selected_group.get("field") or "").strip()
    if field not in {str(column) for column in columns} or (rows and any(field not in row for row in rows)):
        return _selection_boundary(
            status="error",
            message="### 실시간 생산 분석 오류\n공정그룹 필터 컬럼이 판정 데이터에 없어 Report를 생성하지 않았습니다.",
            groups=groups,
            matches=matches,
            errors=[
                {
                    "type": "missing_process_group_field",
                    "message": f"판정 데이터에 metadata field `{field}`가 없습니다.",
                }
            ],
        )

    allowed_processes = {
        str(item).strip().casefold()
        for item in selected_group.get("processes") or []
        if str(item).strip()
    }
    selected_rows = [
        deepcopy(row)
        for row in rows
        if str(row.get(field) or "").strip().casefold() in allowed_processes
    ]
    if not selected_rows:
        return _selection_boundary(
            status="error",
            message=f"### 실시간 생산 분석 오류\n선택한 `{selected_group['display_name']}`의 판정 데이터가 없어 Report를 생성하지 않았습니다.",
            groups=groups,
            matches=matches,
            errors=[
                {
                    "type": "empty_selected_process_group_dataset",
                    "message": f"{field}에 등록 공정({', '.join(selected_group.get('processes') or [])})이 없습니다.",
                }
            ],
        )

    selected = deepcopy(dataset)
    selected["contract_version"] = DATASET_CONTRACT_VERSION
    selected["rows"] = selected_rows
    selected["row_count"] = len(selected_rows)
    selected["processes"] = sorted(
        {
            str(row.get(field) or "").strip()
            for row in selected_rows
            if str(row.get(field) or "").strip()
        }
    )
    selected["selected_process_group"] = {
        "key": selected_group["key"],
        "display_name": selected_group["display_name"],
        "aliases": list(selected_group.get("aliases") or []),
        "field": field,
        "processes": list(selected_group.get("processes") or []),
        "question_evidence": matches[selected_key],
        "llm_reason": "",
    }
    selected["selection_contract_version"] = CONTRACT_VERSION
    selected["selection_provenance"] = _selection_provenance(
        matches,
        selected_key=selected_key,
    )
    selected["unfiltered_row_count"] = len(rows)
    return selected


# Langflow 컴포넌트 클래스: 명시된 단일 공정그룹만 선택하고 미지정·모호 입력에서는 Report 생성을 닫습니다.
class RealtimeProductionDeterministicProcessGroupSelectionGate(Component):
    display_name = "00C 실시간 생산 결정론 공정그룹 선택 Gate"
    description = "질문 원문과 Domain 허용목록만으로 단일 공정그룹을 확정하고 해당 데이터만 통과시킵니다."
    name = "RealtimeProductionDeterministicProcessGroupSelectionGate"
    icon = "ShieldCheck"
    inputs = [
        HandleInput(name="question", display_name="사용자 질문", input_types=["Message"], required=True),
        DataInput(name="process_group_catalog", display_name="공정그룹 카탈로그", required=True),
        DataInput(name="dataset", display_name="전체 판정 데이터", required=True),
    ]
    outputs = [
        Output(
            name="selected_dataset",
            display_name="선택 공정그룹 판정 데이터",
            method="build_selected_dataset",
            types=["Data"],
        )
    ]

    # 함수 설명: `build_selected_dataset()`는 선택 데이터 또는 재질문/error 계약을 Langflow Data로 반환합니다.
    def build_selected_dataset(self) -> Data:
        payload = select_process_group_dataset(
            question_value=getattr(self, "question", None),
            catalog_value=getattr(self, "process_group_catalog", None),
            dataset_value=getattr(self, "dataset", None),
        )
        if payload.get("contract_version") == DATASET_CONTRACT_VERSION:
            group = payload.get("selected_process_group") or {}
            self.status = f"{group.get('display_name') or group.get('key')} / {payload.get('row_count', 0):,}행"
        else:
            self.status = str(payload.get("message") or payload.get("status") or "")
        return Data(data=payload)

# -*- coding: utf-8 -*-
# =============================================================================
# 컴포넌트 개요: 00D Realtime Report View Bundle 생성기
# 역할: 실시간 생산 Report의 업무 계산 결과를 사람이 작성할 JSON 계약이 아닌 간단한 Report View Bundle으로 만듭니다.
# 주요 입력: production.judgement.dataset.v1 Data, 현재 사용자 Message
# 주요 출력: 00E 공용 Report Context Publisher가 소비할 report.view.bundle.v1 Data
# 처리 흐름: 계약·session 검증 -> 생산부족 제품 View 계산 -> View 데이터·표시명·업무 계산 규칙만 Bundle에 기록
# 유지보수 포인트: Query Source 계약·Snapshot 저장·후속 분석 정책은 공용 00E가 자동으로 발행합니다.
# =============================================================================

from __future__ import annotations

from copy import deepcopy
from math import isfinite
from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, HandleInput, Output
from lfx.schema.data import Data


BUNDLE_CONTRACT_VERSION = "report.view.bundle.v1"
DATASET_CONTRACT_VERSION = "production.judgement.dataset.v1"
SOURCE_ALIAS = "report_snapshot"
DATASET_KEY = "production_judgement_snapshot"
SHORTAGE_SOURCE_ALIAS = "report_shortage_products"
SHORTAGE_DATASET_KEY = "report_shortage_products"
PRODUCT_KEY_COLUMNS = ["MODE", "DENSITY", "TECH", "ORG", "PKG1", "PKG2", "LEAD", "MCP_NO"]
SHORTAGE_PRODUCT_COLUMNS = [*PRODUCT_KEY_COLUMNS, "PRODUCTION", "OUT_PLAN", "생산실적달성율", "달성율*판정"]
MAX_QUESTION_CHARS = 4_000


# 함수 설명: `_clean()`은 입력 값을 공백이 제거된 문자열로 정규화합니다.
def _clean(value: Any) -> str:
    return str(value or "").strip()


# 함수 설명: `_clip()`은 사용자·추적 정보에 넣을 문자열 길이를 안전하게 제한합니다.
def _clip(value: Any, limit: int) -> str:
    text = _clean(value)
    return text if len(text) <= limit else text[: max(0, limit - 1)].rstrip() + "…"


# 함수 설명: `_payload()`는 Langflow Data 또는 dict 입력에서 원본 dataset mapping을 꺼냅니다.
def _payload(value: Any) -> dict[str, Any]:
    raw = getattr(value, "data", value)
    return raw if isinstance(raw, dict) else {}


# 함수 설명: `_session_id_from_mapping()`은 호환 가능한 mapping에서 session 식별자를 찾습니다.
def _session_id_from_mapping(value: Any) -> str:
    if not isinstance(value, dict):
        return ""
    for key in ("session_id", "sessionId", "conversation_id", "chat_id", "thread_id"):
        session_id = _clean(value.get(key))
        if session_id:
            return session_id
    return ""


# 함수 설명: `_question_parts()`는 Message에서 질문과 session_id를 함께 추출합니다.
def _question_parts(value: Any) -> tuple[str, str]:
    data = getattr(value, "data", None)
    data = data if isinstance(data, dict) else {}
    question = _clean(getattr(value, "text", None) or data.get("text") or data.get("question"))
    session_id = _clean(getattr(value, "session_id", None) or data.get("session_id"))
    if not session_id:
        for candidate in (data, data.get("metadata"), data.get("properties"), data.get("request")):
            session_id = _session_id_from_mapping(candidate)
            if session_id:
                break
    return _clip(question, MAX_QUESTION_CHARS), session_id


# 함수 설명: `_columns()`는 declared schema와 실제 row key를 결합해 표시 가능한 컬럼을 계산합니다.
def _columns(dataset: dict[str, Any], rows: list[dict[str, Any]]) -> list[str]:
    result: list[str] = []
    for column in dataset.get("columns", []) if isinstance(dataset.get("columns"), list) else []:
        text = _clean(column)
        if text and text not in result:
            result.append(text)
    for row in rows:
        for column in row:
            text = _clean(column)
            if text and text not in result:
                result.append(text)
    return result


# 함수 설명: `_number()`는 결측·비정상 수량을 0으로 처리하는 유한 숫자 변환기입니다.
def _number(value: Any) -> float:
    if value in (None, ""):
        return 0.0
    try:
        number = float(str(value).replace(",", "").strip())
    except (TypeError, ValueError):
        return 0.0
    return number if isfinite(number) else 0.0


# 함수 설명: `_compact_number()`는 정수처럼 보이는 수량을 정수로 표현해 View 표시를 단순화합니다.
def _compact_number(value: float) -> int | float:
    return int(value) if float(value).is_integer() else round(float(value), 6)


# 함수 설명: `_materialize_shortage_products()`는 생산부족 Case를 실제 제품 키 기준으로 집계한 Report View를 생성합니다.
def _materialize_shortage_products(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    grouped: dict[tuple[str, ...], dict[str, Any]] = {}
    for row in rows:
        if _clean(row.get("달성율*판정")) != "생산부족":
            continue
        key = tuple(_clean(row.get(column)) for column in PRODUCT_KEY_COLUMNS)
        current = grouped.get(key)
        if current is None:
            current = {column: deepcopy(row.get(column)) for column in PRODUCT_KEY_COLUMNS}
            current["PRODUCTION"] = 0.0
            current["OUT_PLAN"] = 0.0
            grouped[key] = current
        current["PRODUCTION"] += _number(row.get("PRODUCTION"))
        current["OUT_PLAN"] += _number(row.get("OUT_PLAN"))
    result: list[dict[str, Any]] = []
    for current in grouped.values():
        production = float(current["PRODUCTION"])
        out_plan = float(current["OUT_PLAN"])
        current["PRODUCTION"] = _compact_number(production)
        current["OUT_PLAN"] = _compact_number(out_plan)
        current["생산실적달성율"] = round(production / out_plan * 100, 1) if out_plan else 0.0
        current["달성율*판정"] = "생산부족"
        result.append(current)
    return result


# 함수 설명: `_blocked_bundle()`은 유효하지 않은 Report 입력을 공용 Publisher가 이해할 수 있는 차단 Bundle으로 반환합니다.
def _blocked_bundle(question: str, session_id: str, issue_type: str, message: str) -> dict[str, Any]:
    issue = {"type": issue_type, "message": message}
    return {
        "contract_version": BUNDLE_CONTRACT_VERSION,
        "request": {"question": question, "session_id": session_id},
        "report": {},
        "views": [],
        "trace": {
            "warnings": [],
            "errors": [issue],
            "inspection": {"realtime_report_view_bundle": {"stage": "00d_realtime_report_view_bundle", "status": "blocked", "errors": [issue]}},
        },
    }


# 주요 함수: 실시간 생산 Report의 계산 결과를 공용 Context Publisher가 자동 계약화할 간단한 View Bundle로 변환합니다.
def build_realtime_report_view_bundle(dataset_value: Any, question_value: Any) -> dict[str, Any]:
    dataset = _payload(dataset_value)
    question, session_id = _question_parts(question_value)
    if dataset.get("contract_version") != DATASET_CONTRACT_VERSION:
        return _blocked_bundle(question, session_id, "invalid_report_snapshot_contract", f"Realtime Report에는 {DATASET_CONTRACT_VERSION} 계약이 필요합니다.")
    if not session_id:
        return _blocked_bundle(question, session_id, "missing_session_id", "현재 실행의 session_id를 확인할 수 없어 Report Context를 저장하지 않았습니다.")
    raw_rows = dataset.get("rows")
    if not isinstance(raw_rows, list):
        return _blocked_bundle(question, session_id, "missing_report_snapshot_rows", "선택 공정그룹 판정 데이터의 rows를 확인할 수 없습니다.")
    rows = [deepcopy(row) for row in raw_rows if isinstance(row, dict)]
    if not rows:
        return _blocked_bundle(question, session_id, "empty_report_snapshot_rows", "선택 공정그룹 판정 데이터가 비어 있어 Report Context를 저장하지 않았습니다.")
    columns = _columns(dataset, rows)
    required_shortage_columns = [*PRODUCT_KEY_COLUMNS, "PRODUCTION", "OUT_PLAN", "달성율*판정"]
    missing_columns = [column for column in required_shortage_columns if column not in set(columns)]
    if missing_columns:
        return _blocked_bundle(question, session_id, "report_recipe_schema_invalid", "생산부족 제품 View 계산에 필요한 실제 컬럼이 없습니다: " + ", ".join(missing_columns))
    shortage_rows = _materialize_shortage_products(rows)
    selected_group = dataset.get("selected_process_group") if isinstance(dataset.get("selected_process_group"), dict) else {}
    snapshot_id = _clip(dataset.get("snapshot_id"), 200)
    snapshot_at = _clip(dataset.get("snapshot_at"), 100)
    work_date = _clip(dataset.get("work_date"), 40)
    source_type = _clip(dataset.get("source_type") or "report_snapshot", 80)
    return {
        "contract_version": BUNDLE_CONTRACT_VERSION,
        "request": {"question": question, "session_id": session_id},
        "report": {
            "report_type": "realtime_production",
            "title": "실시간 생산 분석 Report",
            "snapshot_id": snapshot_id,
            "snapshot_at": snapshot_at,
            "scope": {
                "work_date": work_date,
                "process_group": {
                    "key": _clip(selected_group.get("key"), 80),
                    "display_name": _clip(selected_group.get("display_name"), 200),
                    "field": _clip(selected_group.get("field"), 120),
                    "processes": [_clip(item, 120) for item in selected_group.get("processes", []) if _clean(item)][:100],
                },
            },
        },
        "views": [
            {
                "view_key": SOURCE_ALIAS,
                "dataset_key": DATASET_KEY,
                "display_name": "Report 상세",
                "aliases": ["Report 원본", "Report 상세", "원본 판정 데이터", "케이스 상세"],
                "purpose": "case_detail",
                "rows": rows,
                "columns": columns,
                "identity_columns": ["WORK_DATE", "OPER", *PRODUCT_KEY_COLUMNS],
                "grain": {"kind": "case", "unique": False},
                "default_view": True,
                "followup_enabled": True,
                "source_type": source_type,
            },
            {
                "view_key": SHORTAGE_SOURCE_ALIAS,
                "dataset_key": SHORTAGE_DATASET_KEY,
                "display_name": "생산부족 제품",
                "aliases": ["생산부족 제품", "생산 부족 제품", "부족 제품"],
                "purpose": "production_shortage_products",
                "rows": shortage_rows,
                "columns": list(SHORTAGE_PRODUCT_COLUMNS),
                "identity_columns": list(PRODUCT_KEY_COLUMNS),
                "grain": {"kind": "product", "unique": True},
                "metrics": [
                    {"key": "production_quantity", "column": "PRODUCTION", "method": "sum"},
                    {"key": "out_plan_quantity", "column": "OUT_PLAN", "method": "sum"},
                    {"key": "production_achievement_rate", "column": "생산실적달성율", "method": "recompute_ratio", "numerator_column": "PRODUCTION", "denominator_column": "OUT_PLAN", "scale": 100},
                ],
                "predicates": [{"column": "달성율*판정", "operator": "eq", "value": "생산부족", "materialized": True}],
                "lineage": [SOURCE_ALIAS],
                "followup_enabled": True,
                "source_type": "report_materialized_view",
            },
        ],
        "trace": {
            "warnings": [],
            "errors": [],
            "inspection": {
                "realtime_report_view_bundle": {
                    "stage": "00d_realtime_report_view_bundle",
                    "status": "ready",
                    "view_keys": [SOURCE_ALIAS, SHORTAGE_SOURCE_ALIAS],
                    "shortage_product_count": len(shortage_rows),
                    "snapshot_id": snapshot_id,
                    "session_id": session_id,
                    "errors": [],
                }
            },
        },
    }


# Langflow 컴포넌트 클래스: Realtime Report의 업무 계산 결과를 공용 Publisher용 Bundle으로 분리합니다.
class RealtimeProductionReportViewBundleBuilder(Component):
    display_name = "00D Realtime Report View Bundle 생성기"
    description = "실시간 생산 Report의 원본·생산부족 제품 View를 만들고 공용 Context Publisher에 전달합니다."
    name = "RealtimeProductionReportViewBundleBuilder"
    icon = "Layers3"
    inputs = [
